INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(35700, 0, 357, 0, 0, 0, 'Feralas', 'Feralas is a vast, rain-soaked forest in southwestern Kalimdor, green and wild beside the dry lands that surround it. Long ago the night elves built here, and their ruins lie everywhere beneath the canopy, above all the broken city of Eldre''Thalas, now called Dire Maul. Today the Gordunni ogres are the strongest power in the forest, and the land withers wherever they settle. On Sardor Isle, off the western shore, General Shandris Feathermoon holds Feathermoon Stronghold for the Alliance, the tauren of Camp Mojache keep the Horde''s watch in the east, and the small way-station of Thalanaar stands on the border with the Thousand Needles. Neither side has the forest to itself. Woodpaw gnolls, Grimtotem tauren, Northspring harpies and Hatecrest naga each claim a share, the insect hive of the Zukk''ash festers in the southeast, and in the far north the great tree called the Dream Bough rises from an island in Jademir Lake, guarded by the green dragons of the Emerald Dream.', 'warcraft.wiki.gg/wiki/Feralas (rainforest; Gordunni dominant and tainting the land; Feathermoon on Sardor Isle; Camp Mojache; Dream Bough as one of the Great Trees); quest 2981 description (Gordunni the dominant military force in Feralas); quests 2939, 2982 (ruins that cover the forests of Feralas); quest 7441 completion text (Queen, Shen''dralar, Prince Tortheldrin); quest 7481 (Eldre''Thalas, now Dire Maul); quest 4267 description (infestation of southeastern Feralas); zone_areas: Woodpaw, Grimtotem, Northspring, Hatecrest, Zukk''ash spawns; Lethlas, Dreamroarer, Emeriss at area 1111'),
(35701, 1, 357, 1, 0, 0, 'Thalanaar', 'Thalanaar is a small night elf way-station on the eastern edge of Feralas, where the forest gives way to the dry canyons of the Thousand Needles. It offers little more than a hippogryph roost, a pair of merchants and a trainer of tribal leatherworking, yet it matters more than its size suggests. The druid Falfindel Waywarder keeps his post here, and couriers from Feathermoon Stronghold cross the whole breadth of Feralas to bring him supplies. Travelers remark on how abruptly the green forest ends at this border. One scholar who studies the barren lands beyond is sure that strange magic was at work when that happened.', 'warcraft.wiki.gg/wiki/Thalanaar (tiny night elf camp on the border of Feralas and Thousand Needles; Caryssia Moonhunter, Rendow, Brienna Starglow, Thyssiana); zone_areas area 489: Falfindel 4048, Thyssiana 4319, Caryssia 7870, Rendow 1695, Brienna 6576; quest 4281 description and reward text (parcel from Feathermoon, small way-station of Thalanaar); quest 4125 description (Raschal set out for Thalanaar); quest 3841 request text (Quentin: odd transition between Feralas and Thousand Needles, strange magic)'),
(35702, 1, 357, 2, 0, 0, 'Camp Mojache', 'Camp Mojache is the Horde''s foothold in Feralas, a tauren camp of hide tents built astride a swift stream above Wildwind Lake. Braves guard its paths, and it has an inn, a wind rider roost and trainers of many crafts. It is a meeting place as much as a village. The elder Talo Thornhoof tells his stories here, the troll Witch Doctor Uzer''i studies the spirits of beasts, the warrior Rok Orhan leads the fight against the ogres, and Krueg Skullsplitter has come on an errand from Orgrimmar. Its neighbors give it little peace. Woodpaw gnolls press up from the south with growing fury, and the Gordunni hold the river valley to the north.', 'warcraft.wiki.gg/wiki/Camp_Mojache (tauren village overlooking Wildwind Lake, straddles a fast-moving stream; inn, flight master, trainers); zone_areas area 1099: Camp Mojache Braves, Innkeeper Greul, Shyn, Talo 7776, Uzer''i 8115, Rok Orhan 7777, Krueg 4544, Hadoken 7875; quest 7492 (Talo Thornhoof, a tauren elder); npc_text 3545 (Talo: listen to the stories of an elder); quest 2981 (Rok Orhan, a warrior); quest 2973 (Krueg on a mission for Orgrimmar masters); quests 2862, 2975 (gnolls from the south, Gordunni north along the river)'),
(35703, 1, 357, 3, 0, 0, 'Lariss Pavilion', 'North of Camp Mojache stands Lariss Pavilion, a large open-air hall raised in the old night elf style. Its strangest tenant is Azj''Tordin, a Highborne who slipped out of Dire Maul and the grip of its mad prince. He lingers here among the old stones, savoring the freedom for which he gave up his immortality, though he fled the city in such haste that he was robbed on the way. A door at the foot of the pavilion is said to lead back into the old city.', 'warcraft.wiki.gg/wiki/Lariss_Pavilion (night elf-style outdoor building north of Camp Mojache; Azj''Tordin escaped Dire Maul through a back door at the bottom of the Pavilion; Xerash Fireblade); quest 7441 description and completion text; quests 3121, 3122 (Xerash Fireblade at the Lariss Pavilion, shrunken head for herbs); zone_areas area 2518: Azj''Tordin 14355, Xerash Fireblade 36208, Door 177198; warcraft.wiki.gg/wiki/Xerash_Fireblade (orc, added in patch 3.2.0, quests 3121/3122); quest 7441 description (in my haste to escape the grip of the fallen Prince, I was robbed)'),
(35704, 1, 357, 4, 0, 0, 'Gordunni Outpost', 'Following the river north from Camp Mojache leads to the Gordunni Outpost, a camp of the ogres who dominate Feralas. Ogres, brutes and ogre magi crowd it, and the land around them bears the scars of their presence. They guard more than their tents. The Gordunni bury a mineral called Gordunni cobalt in the earth here, betrayed only by its blue glow, and a goblin prospector newly arrived at Camp Mojache wants it dug up, sure it will fetch a pretty price. Soiled scrolls lie about the camp as well, and one of them seems to depict some sort of meeting or ceremony of the ogres, a puzzle that Rok Orhan of Camp Mojache would dearly like to see solved.', 'quest 2975 description (follow the river north to their outpost; their presence scars the land); quest 2987 description (Orwin Gizzmick, Gordunni cobalt, blue glow, dig); quests 2978, 2979 (Gordunni Scroll, ceremony of the mage-lords); zone_areas area 1103: Gordunni Ogre, Brute, Ogre Mage; gameobject 143980 Gordunni Scroll; warcraft.wiki.gg/wiki/Orwin_Gizzmick (goblin at Camp Mojache)'),
(35705, 1, 357, 5, 0, 0, 'Woodpaw Hills', 'South of Camp Mojache, the wooded hills belong to the Woodpaw gnolls, who keep a den deep among them. Mystics, reavers, trappers and brutes fill their camps, and their leaders call themselves Alphas. Their raids on the tauren have grown more frequent and more savage, almost as if the gnolls were desperate, and Camp Mojache wonders what has driven them into such a frenzy. Like all gnolls they keep what they scavenge and fight over it. A rare treant, Gnarl Leafbrother, is sometimes seen among the hills.', 'zone_areas areas 2519, 2520: Woodpaw Mystic, Reaver, Trapper, Brute, Alpha; Gnarl Leafbrother 5354; Woodpaw Battle Map 142195; Large Leather Backpacks 164953; quests 2862, 2863, 2903 reward texts (attacks more savage, almost desperate; Alphas; two-front war); quests 4131, 4135 (gnolls keep items they scavenge; backpacks tacked to a tree); warcraft.wiki.gg/wiki/Gnarl_Leafbrother (rare treant); quest 2862 request text (someone or something must be driving them into a frenzy)'),
(35706, 1, 357, 6, 0, 0, 'The Writhing Deep', 'Beyond the Woodpaw camps in southeastern Feralas, the earth is broken into the twisted mounds and tunnels of the Writhing Deep, a hive of the insects known here as the Zukk''ash. Workers, wasps, stingers and tunnelers swarm over its slopes, and even the ore in its veins comes smeared with ooze. Among them roams Stinglasher, far larger than its kin and wrapped in an aura the others lack.', 'quest 4135 description and reward text (Writhing Deep south of the gnoll camps; pod encasing a humanoid); quest 4265 (Raschal paralyzed inside the pod); quest 7731 description (Stinglasher, larger, secretes an aura); quest 7730; quests 4267, 7732 reward texts (silithid); zone_areas area 1101: Zukk''ash Tunneler, Wasp, Worker, Stinger; Stinglasher 14661; Qirot; Ooze Covered deposits 123309/123310'),
(35707, 1, 357, 7, 0, 0, 'Grimtotem Compound', 'East of Dire Maul, the Grimtotem tribe has raised a compound of tents in the Feralas woods, guarded by raiders, shamans and naturalists. These tauren are hostile to every outsider, and their work here is dark. In a bamboo pen nearby they keep captured sprite darters, the faerie dragons of the forest, for purposes no one has learned. Two night elves, Kindal Moonweaver and the priestess Jer''kai, keep watch over the camp from a rise above it. The Horde has taken notice too: in Orgrimmar, Belgrom Rockmaul has put a bounty on the clan''s horns.', 'warcraft.wiki.gg/wiki/Grimtotem_Compound (east of Dire Maul; cage of imprisoned sprite darters); quest 2969 description (Grimtotem capturing faerie dragons, no idea what they plan, cage); quest 2970 description (camp below us); quest 2972 reward (Jer''kai a priestess of Tyrande); quest 2974 description (Belgrom''s bounty); zone_areas area 1100: Grimtotem Naturalist, Raider, Shaman; Captured Sprite Darters and Kindal/Jer''kai stand just outside at -4540,815 and -4481,858'),
(35708, 1, 357, 8, 0, 0, 'Dire Maul', 'In the heart of Feralas rise the broken walls of Eldre''Thalas, a city of Queen Azshara''s Highborne, its great halls now called Dire Maul. The Queen is long gone, and the Shen''dralar who linger within have been marred by the madness of their Prince Tortheldrin. Gordok ogres hold the grounds outside, their hyenas prowling among the fallen stones, and in an arena within the walls, the Maul, ogre champions brawl while spectators such as Griniblix cheer them on. Deeper in, the wings hold satyrs, a rogue blood elf mage and perhaps the last refuge of a lost elven master.', 'warcraft.wiki.gg/wiki/Dire_Maul (Eldre''Thalas, Highborne capital of Azshara; Shen''dralar; Tortheldrin; Gordok); quest 7441 completion text (Queen long passed, Shen''dralar marred by Prince Tortheldrin''s madness); quest 7481 (Eldre''Thalas, now Dire Maul; Kariel Winthalus); quest 7488 (Lethtendris among the satyrs in Warpwood); zone_areas area 2577: Gordok Ogre-Mage, Enforcer, Gordok Hyena; posarea: Griniblix 14395, Mushgog, Skarr, The Razza in area 3217 The Maul (instance-zone area, not used as a trigger); npc_text 11738 (Griniblix: they are into it now)'),
(35709, 1, 357, 9, 0, 0, 'The High Wilderness', 'The High Wilderness spreads across the uplands of southern Feralas, a broad country of forest glades and broken ground. Groddoc apes, ironfur bears and longtooth howlers roam it, Frayfeather hippogryphs wheel over its clearings, and Feral Scar yetis prowl its slopes. This was once night elf land, and its abandoned, ruined buildings still stand. The Gordunni ogres have claimed them, and where they dwell the trees wither and the ground is desecrated. The Feathermoon scholar Troyas Moonbreeze often comes here alone to study the ruins, much to the worry of Angelas Moonbreeze.', 'quest 2980 description (High Wilderness, abandoned structures on land that once belonged to the night elves, withered trees and desecrated terrain, Gordunni); quest 2982 description (Troyas going alone to the High Wilderness; Gordunni took over); zone_areas area 1136: Groddoc Ape, Frayfeather Hippogryph and Stagwing, Ironfur Bear, Longtooth Howler, Hulking and Enraged Feral Scar, Gordunni'),
(35710, 1, 357, 10, 0, 0, 'Ruins of Isildien', 'Deep in the High Wilderness lie the Ruins of Isildien, the remains of a large night elf city destroyed long ages ago. A broad stair climbs to a round hall that may once have been a temple. The Gordunni have made the ruins their stronghold, and here gather their mightiest: battlemasters, warlords, warlocks, maulers and the mage-lords of the tribe. Their magic seems to wreak havoc on the very ground they stand on. Frayfeather hippogryphs still nest at the edges of the ruins, and an old bear called Old Grizzlegut is known to wander nearby.', 'warcraft.wiki.gg/wiki/Ruins_of_Isildien (large night elven city in southwestern Feralas, Gordunni home; round building at the end of the stairs may have been a temple of Elune); quest 2982 request text (Gordunni magic wreaks havoc on the land they stand on); quest 2979 (mage-lords'' ceremony); zone_areas area 2522: Gordunni Battlemaster, Warlord, Mage-Lord, Warlock, Shaman, Mauler; Frayfeather Skystormer, Patriarch; Hippogryph Egg x7; Old Grizzlegut 5352 (family bear)'),
(35711, 1, 357, 11, 0, 0, 'Feral Scar Vale', 'Feral Scar Vale is a valley of yetis in southern Feralas, just inland of the Forgotten Coast. Its yetis grow hides so thick that leatherworkers in both Feathermoon Stronghold and Camp Mojache prize them, claiming that properly treated they are as strong as iron. A rare brute called Bloodroar the Stalker hunts the vale. In a cave nearby lies a stranger find: OOX-22/FE, a gnomish homing robot that looks rather like a chicken. It crashed here, and its maker in Booty Bay calls for someone to carry a beacon to it and escort it safely to the road.', 'quests 2821, 2822 (thick yeti hides, Feral Scar Vale just inland of the Forgotten Coast, stronger than iron); quests 2766, 2767 (OOX-22/FE in a cave near Feral Scar Vale, Oglethorpe Obnoticus in Booty Bay, escort to the main road); zone_areas area 1105: Feral Scar Yeti, Enraged Feral Scar, Bloodroar the Stalker 5346, Homing Robot OOX-22/FE 7807'),
(35712, 1, 357, 12, 0, 0, 'Frayfeather Highlands', 'In the far south of Feralas, the Frayfeather Highlands are home to great flocks of wild hippogryphs: stagwings, skystormers and the proud patriarchs that lead them. Hippogryphs have been loyal companions to the night elves for many years, and their eggs can be found in nests across these heights. That loyalty has drawn unwelcome attention, for Witch Doctor Uzer''i of Camp Mojache covets the steadfast spirits of these birds for his muisek magic. The greatest of the flock, a hippogryph known as Antilus the Soarer, is seldom seen.', 'zone_areas area 1106: Frayfeather Skystormer, Stagwing, Patriarch; Antilus the Soarer 5347; Hippogryph Egg 141931; quest 3124 description (hippogryphs loyal companions to the night elves, spirits loyal and steadfast)'),
(35713, 1, 357, 13, 0, 0, 'The Twin Colossals', 'Two immense peaks of rock tower over northwestern Feralas, the highest points in the land, and the road to Desolace runs between them. Mountain giants stride across the rocky ground at their feet, and Groddoc thunderers, ironfur patriarchs and rabid longtooths make every path dangerous. A few odd souls camp here. Marli Wishrunner can send a traveler to the top of a colossal, though only one way, and Kalin Windflight waits at the summit selling wings for the trip down. The gentle giant Rockbiter keeps a camp south of the Ruins of Ravenwind, and Gregan Brewspewer, a student of herbs who is hard to track down, keeps a camp out in these wilds.', 'warcraft.wiki.gg/wiki/Twin_Colossals (two tall mesas, highest points, road to Desolace between them; Marli''s one-way trip; Kalin sells the Colossal Parachute); quest 3567 reward text (one way trip only); npc_text 2054 (Kalin: wings to get down); creature 7772 at z 246, vendor item 10684; zone_areas area 1119: Cliff Giant, Land Walker, Groddoc Thunderer, Ironfur Patriarch, Rabid Longtooth; Rockbiter 7765, Gregan 7775, Marli 7773, Kalin 7772; quest 3909 description (Gregan hard to track down, camping in the wilds of Feralas); quest 4041 (herbs and alchemy); quest 4142'),
(35714, 1, 357, 14, 0, 0, 'Ruins of Ravenwind', 'West of the Dream Bough lie the Ruins of Ravenwind, remains of an ancient night elf city now overrun by the Northspring harpies. Their queen, Edana Hatetalon, is said to have a heart of crystal, empty of all but hatred, and she comes when a harpy horn is sounded by the Hatetalon stones in the northern ruins. Older magic lingers among the stones. Four flames named Samha, Imbel, Byltan and Lahassa still burn there, and the Equinex Monolith stands silent nearby, keeping whatever it holds. On the eastern edge of the ruins, a gnoll named Miblon Snarltooth stands guard over a patch of evoroot.', 'warcraft.wiki.gg/wiki/Ruins_of_Ravenwind (ancient kaldorei city, Northspring harpies; Miblon Snarltooth guarding Evoroot); quest 2879 description (Ruins of Ravenwind west of the Dream Bough; four flames; Equinex Monolith); quest 3062 description (Edana Hatetalon, queen, heart of crystal, horn by the Hatetalon stones in the north of the ruins); zone_areas area 1114: Northspring Windcaller, Harpy, Slayer, Roguefeather; Flames of Byltan, Lahassa, Imbel, Samha; Equinex Monolith 144063; Evoroot 164798; Miblon 9467; warcraft.wiki.gg/wiki/Miblon_Snarltooth (gnoll guarding Evoroot on the eastern outskirts; removed in 4.0.3a); quest 2879 request text (the Equinex Monolith stands silently among the ruins)'),
(35715, 1, 357, 15, 0, 0, 'The Dream Bough', 'In the far north of Feralas, Jademir Lake spreads its quiet waters around an island where a towering tree, the Dream Bough, rises above the forest. It is one of four great trees through which the Emerald Dream touches the waking world; the others stand in Duskwood, the Hinterlands and Ashenvale. The green dragonflight guards it jealously. The dragons Lethlas and Dreamroarer keep watch over the island, and Jademir dragonkin patrol the lake shores and the grounds of Oneiros. Few mortals linger.', 'warcraft.wiki.gg/wiki/Dream_Bough (Great Tree on an island in Jademir Lake, a portal to the Emerald Dream guarded by the green dragonflight); warcraft.wiki.gg/wiki/Emeriss (corrupted green dragon, one of the four world dragons since patch 1.8); zone_areas areas 1111, 1112, 1113: Lethlas 5312, Dreamroarer 12497, Emeriss 14889 (area 1111); Jademir Oracle, Tree Warder, Boughguard (dragonkin, faction 50); warcraft.wiki.gg/wiki/Twilight_Grove, Seradane, Bough_Shadow (the other three great trees)'),
(35716, 1, 357, 16, 0, 0, 'The Forgotten Coast', 'The Forgotten Coast is the western shore of Feralas, looking out across the water to Sardor Isle. Elementals of brine and sea spray rise from the surf, coast crawl creatures scuttle on the sand, and towering giants of the shore and the deep wade through the shallows. A dock here serves the ferry to Feathermoon Stronghold, and beside it the goblin Zorbin Fandazzle is trying, with growing doubts, to run an engineering shop. Not every boat makes its crossing. The wreck of a row boat lies in the muddy water nearby, its side torn open as if something had tried to snap it in two.', 'zone_areas area 1108: Sea Spray, Sea Elemental, Shore/Deep/Wave Strider (giants, type 5), Coast Crawl Snapclaw/Deepseer, Zorbin Fandazzle 14637, Wrecked Row Boat 164909; transports: The Forgotten Coast to Feathermoon Stronghold boat (Feathermoon Ferry); quests 7003, 7721 (Zorbin at the docks of the Forgotten Coast); quest 4125 reward text (wrecked row boat, Feathermoon crest, something tried to snap it in two)'),
(35717, 1, 357, 17, 0, 0, 'Sardor Isle', 'Sardor Isle lies off the Forgotten Coast, a forested island that the night elves of Feathermoon Stronghold have made their own. Beyond the stronghold''s walls the island is wild. Coast crawl snapclaws and deepseers swarm its beaches, longtooth runners hunt in its woods, and a rare beast called Diamond Head lurks along its shore. South of the stronghold, the Ruins of Solarsal have fallen to the Hatecrest naga, and the Sentinels fear that the naga mean in time to seize the whole island. The Isle of Dread lies across the water beyond.', 'zone_areas area 1120: Coast Crawl Snapclaw, Deepseer, Longtooth Runner, Hatecrest naga, Diamond Head 5345; quest 2866 (Ruins of Solarsal to our south); quest 2869 description (naga will eventually move to secure the island); quest 2870 (Isle of Dread across the water)'),
(35718, 1, 357, 18, 0, 0, 'Feathermoon Stronghold', 'Feathermoon Stronghold is the Alliance bastion of Feralas, a night elf fortress on Sardor Isle reached by ferry from the Forgotten Coast or on hippogryph wings. General Shandris Feathermoon led an expeditionary force here and commands it still, with Feathermoon Sentinels on watch. It is a place of scholars as much as soldiers. Troyas and Angelas Moonbreeze pore over their books on the ruins of Feralas, the priestess Vestia Moonspear is one of the most learned minds to be found anywhere, the druid Quintis Jonespyre keeps a tree house, and a history of the Sentinels and the Long Vigil is kept for visitors. Its defenders watch two foes: the naga to the south and the Horde.', 'warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic) (island fortress on Sardor Isle, Shandris, boat from the Forgotten Coast, hippogryph flight point); quest 4125 description (General Feathermoon led the expeditionary forces here); quest 3130 description (stronghold open to direct attack from the Horde); quests 2939, 2871, 4129 (Moonbreezes'' books, Vestia scholar, Quintis'' tree-house); zone_areas area 1116: Feathermoon Sentinel 7939, Shandris 3936, Fyldren Moonfeather 8019; gameobject 175732 The Sentinels and the Long Vigil'),
(35719, 1, 357, 19, 0, 0, 'Ruins of Solarsal', 'The Ruins of Solarsal, on Sardor Isle south of Feathermoon Stronghold, are far older than any of the night elves'' present works. The Sentinels once explored them, found nothing of note and left them in peace. Now the Hatecrest naga have filled them in alarming numbers: warriors, screamers, sirens and wave riders. At the heart of the ruins stands a gazebo that does not belong. It is clearly newer than the stones around it, its sides are engraved with a repeating band of unknown glyphs, and its stone is warm to the touch.', 'quest 2866 description and reward text; zone_areas area 1117: Hatecrest Screamer, Warrior, Siren, Wave Rider; Solarsal Gazebo 142179'),
(35720, 1, 357, 20, 0, 0, 'Isle of Dread', 'South of Sardor Isle, across the water, lies the Isle of Dread. Hatecrest serpent guards, myrmidons and sorceresses hold a deep cave at its northern end, Shalzaru''s Lair, the seat of Lord Shalzaru, one of the crueler naga royals. A hidden passage beneath the waves is said to lead to an inner chamber where Lady Szallah dwells. The heart of the island, a valley walled in by cliffs, belongs to beasts deadlier still: the chimaerok, great two-headed hunters, led by the mighty Lord Lakmaeran.', 'warcraft.wiki.gg/wiki/Isle_of_Dread (south of Sardor Isle; central valley enclosed by cliffs; chimaerok; Lord Lakmaeran; naga cave at the northern end with Lord Shalzaru; underwater passage to Lady Szallah); quest 2870 description (royals, Lord Shalzaru, relic from an excavation in a cave on the Isle of Dread); zone_areas area 1121: Hatecrest Serpent Guard, Sorceress, Myrmidon; Chimaerok, Arcane Chimaerok, Chimaerok Devourer; Lord Lakmaeran 12803; Lord Shalzaru 8136; Lady Szallah 5343'),
(35721, 2, 357, 1, 1, 0, 'Shandris Feathermoon', 'Shandris Feathermoon is General of the Sentinel Army and the commander of Feathermoon Stronghold. Orphaned when the Burning Legion destroyed her village during the War of the Ancients, she was taken in by Tyrande Whisperwind and grew up at her side, through the Sundering and the long ages of the Sentinels, until she rose to lead them. In Feralas she weighs every move against the safety of her island. She would gladly throw her full strength against the Hatecrest naga, but she will not leave the stronghold open to the Horde.', 'warcraft.wiki.gg/wiki/Shandris_Feathermoon (Ara-Hinam destroyed by the Legion, adopted by Tyrande, Sundering, Sentinels, general based at Feathermoon); creature_template 3936 subname General of the Sentinel Army, faction 124; quest 3130 description (full force vs. leaving the stronghold open to the Horde); quest 3788 reward text (General Shandris Feathermoon and the Protectorate); quest 4267'),
(35722, 2, 357, 2, 1, 0, 'Latronicus and Vestia Moonspear', 'Latronicus Moonspear is Shandris Feathermoon''s second, charged with meeting the naga directly. He has no patience for idle talk and is proud of his people''s restraint: the night elves are no warmongers, he says, but they will act to protect their own. When the blood elf mage Lethtendris fled into Dire Maul with a web of stolen magic, it was Latronicus who called for agents to stop her. His wife Vestia is a priestess of the stronghold and one of its most learned scholars, and Latro, as she calls him when she forgets herself, brings her the puzzles he cannot solve.', 'quest 3130 description (Latronicus is her second); quest 2869 request text (not warmongers, will proactively protect our interests); quests 7494, 7488 (Lethtendris); quest 2871 description and request text (Vestia, priestess and scholar; Latro, erm, Latronicus)'),
(35723, 2, 357, 3, 1, 0, 'Quintis Jonespyre', 'Quintis Jonespyre is the druid of Feathermoon Stronghold, a humble servant of Malfurion and the Cenarion Circle who keeps a little tree house within its walls. Curses are his specialty, and he can read the history of an object by touch, a draining art he calls psychometry. His luck at cards is another matter. The stronghold calls him the King of the Bad Beats, and he owes Ginro Hearthkindle for his losses at Kalimdor Hold ''Em.', 'quest 3788 reward text (druid, servant of Malfurion and the Cenarion Circle); quest 3791 description and reward text (curses are my specialty; Staghelm and morrowgrain); quest 3792 reward text (something fishy); quests 4129, 4130 (psychometry, tree-house, Kalimdor Hold ''Em debt, King of the Bad Beats)'),
(35724, 2, 357, 4, 1, 0, 'Troyas and Angelas Moonbreeze', 'Troyas and Angelas Moonbreeze are scholars of Feathermoon Stronghold who comb the ruins that cover the forests of Feralas for what they can tell of the past. Troyas is the bolder of the two. He ventures alone into the ogre-held High Wilderness, and from the rubble of the south he once pulled a stave that he was sure was more than it seemed, though a colleague in Rut''theran grumbles that he always thinks he has found something important. Angelas worries over him, and quietly asks travelers to thin the Gordunni in his path, begging them not to tell him. She also sends the curious to the goblin Marvon Rivetseeker to learn of the Sunken Temple.', 'quest 2982 description and reward text (investigating the ruins; Troyas alone in the High Wilderness; don''t mention a word to Troyas); quest 2939 description and reward text (stave; Daryn: Troyas always thinks he has found something important); quest 3445 description (Marvon Rivetseeker, much like Troyas and I, has studied ancient areas)'),
(35725, 2, 357, 5, 1, 0, 'Falfindel Waywarder', 'Falfindel Waywarder is a night elf druid who keeps his post at Thalanaar, the small way-station where the green forest of Feralas gives way to the dry canyons of the Thousand Needles. It is a lonely posting at the far end of the forest from Feathermoon Stronghold, whose couriers cross the whole breadth of Feralas to bring him his supplies. Yet his name is known well beyond Feralas, further than so small a post would suggest.', 'item 5790 page_text 433-435 (Heralath: word must reach Falfindel Waywarder in Thalanaar; the druid known as Falfindel); quest 1101 reward text (studies in the area; corruption of Agamaggan''s resting place; treachery); quest 4281 reward text (delivery from Feathermoon; Woodpaw highly agitated from a source to their south); creature_template 4048 faction 80 (hostile to the Horde)'),
(35726, 2, 357, 6, 1, 0, 'Rockbiter', 'Rockbiter is a mountain giant who camps at the foot of the Twin Colossals, south of the Ruins of Ravenwind, and for all his size he is gentle and plain of speech. His charge is a little night elf girl named Shay Leafrunner, and watching over her is harder than it sounds. Shay loves to wander and drifts away whenever something lovely catches her eye. When she slipped off from him in the ruins to the north, Rockbiter was sick with worry and hardly knew what to do, and he hoped that someone with quicker legs than his would go and look for her.', 'warcraft.wiki.gg/wiki/Ruins_of_Ravenwind (Shay escorted back to her guardian Rockbiter, a mountain giant south of the ruins); quest 2844 description (Rockbiter lost Shay in the ruins just north); quest 2845 description and reward text (Shay''s bell); creature 7765 in area 1119; faction 124; quests 2844/2845 Alliance only'),
(35727, 2, 357, 7, 2, 0, 'Talo Thornhoof', 'Talo Thornhoof is a tauren elder of Camp Mojache who is always glad to share his stories. In his day he was a seasoned hunter who feared no creature, until Northspring harpies ambushed him in the forest and he barely dragged himself to safety. He was never the same, and the hate still boils in him. He longs for revenge on the harpies and for the crystal heart of their queen, Edana Hatetalon. He still thinks like a hunter: know your enemy, he teaches, and he sends the bold to test the fel-maddened beasts of Felwood. When the blood elf Lethtendris carried her web into Dire Maul, Talo called for help.', 'npc_text 3545 (Listen to the stories of an elder); quest 3063 description (seasoned hunter, ambushed by harpies, hate boils inside); quest 3062 description (Edana Hatetalon''s dark heart); quest 4120 description and reward text (Felwood, always know your enemy); quests 7492, 7489 (Talo Thornhoof, a tauren elder; Lethtendris''s Web)'),
(35728, 2, 357, 8, 2, 0, 'Krueg Skullsplitter', 'Krueg Skullsplitter is an orc who traveled down to Feralas with his companions on a mission for his masters in Orgrimmar. Between duties he has a gentler errand. His life-mate Korrin takes great pleasure in new clothing, and he means to make her a cloak adorned with the shimmering wings of the sprite darters west of Camp Mojache. He warns that the little dragons can be dangerous and that the night elves in the forests are worse. News of Grimtotem in the woods alarms him. He calls the clan evil and wants their horns by the pile, for Belgrom Rockmaul, one of his masters in Orgrimmar, has an interest in their kind and has put a bounty on them.', 'quest 2973 description and request text (mission for Orgrimmar masters, life-mate Korrin, gossamer wings, night elves); quest 2974 description and request text (Grimtotem, Belgrom''s bounty, the clan is evil); quest 2976 description (crate of horns to Belgrom in the Valley of Honor); creature_template 4544 faction 29 (Orgrimmar)'),
(35729, 2, 357, 9, 0, 0, 'Azj''Tordin', 'Azj''Tordin is a Highborne who fled the halls of Eldre''Thalas and now lingers at the Lariss Pavilion. The Queen has long since passed, he says, and the works of the Shen''dralar have been marred by the madness of Prince Tortheldrin. He has traded his immortality for freedom and regrets nothing. In the haste of his escape, though, he was robbed. The imp Pusillin made off with his book of incantations and with the key to the once great halls. The key he no longer cares for. The book he wants back badly, and he waits for someone bold enough to chase the imp through the Warpwood Quarter.', 'quest 7441 description and completion text; warcraft.wiki.gg/wiki/Lariss_Pavilion (Azj''Tordin, apparently a Highborne); creature_template 14355 faction 1354 (Shen''dralar, neutral to both factions)'),
(35730, 2, 357, 10, 0, 0, 'Zorbin Fandazzle', 'Zorbin Fandazzle is a goblin engineer who has set up shop beside the dock on the Forgotten Coast against his own better judgment, and now suspects it may be the worst place imaginable. The giants of Feralas are bad for business, so he has built an Ultra-Shrinker, a gnomish shrinking ray improved with superior goblin know-how, and wants someone to try it on them. Then there are the sea elementals of the coast, whose water cores make fine fuel for his device. He insists there was never any danger, pays in coin and loot, and swears that his comrades in the Steamwheedle Cartel will hear of anyone who helps him.', 'quests 7003, 7721, 7725, 7726 descriptions and reward texts; npc_text 7114, 7116 (maybe this wasn''t the best place for a shop); creature_template 14637 faction 35'),
(35731, 3, 357, 1, 1, 0, 'Lonebrow''s Journal', 'Henrig Lonebrow came to Kalimdor for the Explorers'' League, hunting the bones of a fallen god in the Barrens, until the boar men of the Razorfen dragged him into the thorns of Razorfen Kraul. There he shared a hut with Heralath, a dying druid who had come to learn why the resting place of the boar god Agamaggan, held to be pure, had been so corrupted. Before his strength failed, Heralath begged the dwarf to carry word to Falfindel Waywarder at Thalanaar: the crone Charlga Razorflank was rousing her minions, and she had to be stopped before her corruption spread. Lonebrow escaped but never reached Thalanaar, and his journal was found on his body.', 'item 5790 Henrig Lonebrow''s Journal, page_text 424-435; quest 1100 reward and completion texts (journal found on a deceased dwarf); quest 1101 description and reward text; thousand_needles.json 40001 (body at the Great Lift; Thousand Needles leaves 1100 to Feralas)'),
(35732, 3, 357, 2, 1, 0, 'The Hatecrest Naga', 'The Ruins of Solarsal, south of Feathermoon Stronghold on Sardor Isle, far predate the night elves'' present works. The Sentinels explored them once, found nothing of note and left them in peace. Now the Hatecrest naga have occupied them in alarming numbers. At first Shandris Feathermoon took it for the prelude to an attack on her island, and that threat has not passed, but she suspects that something else is going on among the old stones, and she has sent an investigator south to look for anything that stands out.', 'quests 2866, 2867, 3130, 2869, 2870, 2871 descriptions and reward texts'),
(35733, 3, 357, 3, 1, 0, 'The Missing Courier', 'Raschal has carried Feathermoon''s messages since Shandris Feathermoon brought her expedition to Feralas, and he knows the forest well. About a week ago he set out for Thalanaar, meaning to row down the coast and cross southern Feralas to avoid the Horde camp, and he never arrived. The stronghold''s own searches found nothing, and Latronicus Moonspear has had to declare him missing in action. His friend Ginro Hearthkindle would not give up, though every day''s search in the wilds brought him back nothing but gnoll teeth and disappointment.', 'quests 4124, 4125, 4127, 4129, 4130, 4131, 4135, 4265, 4266, 4267 descriptions and reward texts; quest 4281 (parcel for Falfindel)'),
(35734, 3, 357, 4, 1, 0, 'Freedom for All Creatures', 'From a rise above the Grimtotem Compound, Kindal Moonweaver and the priestess Jer''kai keep watch on the tauren below. The filthy Grimtotem, as Kindal calls them, are capturing faerie dragons, the sprite darters of the forest, and penning them in a bamboo cage, and neither elf can guess what for. The two are not strong enough to fight their way into the camp alone. Kindal''s plan is to carry a cage key into the compound with a helper and some strong friends, throw open the pen and stay beside the darters until they escape with their lives, while Jer''kai keeps her post on the rise.', 'quests 2969, 2970, 2972 descriptions and reward texts; quests 3841, 3842, 3843, 4297, 4298 (sprite darter egg, Quentin, Agnar Beastamer at Aerie Peak); hinterlands.json 4702 mentions Agnar hatching faerie dragon eggs from Feralas, no triggers on these quests'),
(35735, 3, 357, 5, 1, 0, 'The Stave of Equinex', 'Searching the rubble to the south a few days ago, Troyas Moonbreeze found a stave that looks ordinary, yet he cannot shake the feeling that it is something more. The ruins of Feralas are dangerous, but they have much to tell of what happened here. He and Angelas have pored over their books at Feathermoon Stronghold without finding a word about it, so Troyas has sent for help to a colleague in Darnassus, the lore keeper Daryn Lightwind of Rut''theran Village.', 'quests 2939, 2940, 2941, 2944, 2943, 2879, 2942 descriptions and reward texts'),
(35736, 3, 357, 6, 2, 0, 'War on the Woodpaw', 'To Hadoken Swiftstrider of Camp Mojache, the Woodpaw gnolls are more than a nuisance: they are a constant threat to the camp''s very existence. Whether or not they belong in Feralas matters little to him. If the tauren do not strengthen their resolve, he warns, they will find themselves driven out of the whole region, and the gnoll attacks have grown more fevered of late. Hadoken has answered with a bounty on Woodpaw manes, and he suspects that someone or something is driving the gnolls into a frenzy.', 'quests 2862, 2863, 2902, 2903, 7730, 7731, 7732 descriptions and reward texts'),
(35737, 3, 357, 7, 2, 0, 'The Ogres of Feralas', 'In Orgrimmar, Belgrom Rockmaul calls the Gordunni ogres the dominant military force in Feralas, and their numbers are growing. They must be stopped before they threaten the Horde''s presence there, and he sends the willing to the warrior Rok Orhan at Camp Mojache. Rok Orhan has seen what the ogres do: their very presence scars the land, and she means to push them back before they spread further into the forest, beginning with their outpost up the river to the north. A soiled scroll from that outpost raises a darker question, for it seems to depict some sort of meeting or ceremony of the Gordunni.', 'quests 2981, 2975, 2980, 2978, 2979, 3002 descriptions and reward texts'),
(35738, 3, 357, 8, 2, 0, 'The Muisek', 'Witch Doctor Uzer''i, a troll of Camp Mojache, teaches that incredible power can be found in the muisek, the spirits of the creatures one battles against, and he means to harness that power for the Horde. To prepare a vessel for the work, he needs herbs from an orc named Fireblade, mixed to his order and paid for with a shrunken head taken from some poor dwarf he came across in the forest. For the endeavor that is to follow he gathers natural materials as well: splintered logs from the treants of Feralas, minerals crusted on mountain giants and faerie dragons, resilient sinew from owlbeasts or hippogryphs, and a great many metallic fragments.', 'quests 3121-3129 descriptions and reward texts; npc_text 1757 (Uzer''i on muisek); mod-individual-progression zone_orgrimmar.sql and zone_feralas.sql (3121 and 3122 rerouted to Neeru Fireblade 3216; 3123 changed to wildkin of the Hinterlands)'),
(35739, 3, 357, 9, 0, 0, 'Errands in Eldre''Thalas', 'Both camps of Feralas send champions into Dire Maul. Lethtendris, a blood elf mage whose brutality is matched only by her craving for magic, has fled into the Warpwood Quarter among the satyrs and woven a web to snare the magical energies of the place. Heralds in the capitals call for agents, sending the Alliance to Latronicus Moonspear and the Horde to Talo Thornhoof. A quieter search is shared by two scholars, Sage Korolusk of Camp Mojache and Scholar Runethorn of Feathermoon, who work together despite their banners. They hunt for Kariel Winthalus, an elven master who fled the ruin of Quel''Thalas with ancient artifacts, and they followed his trail across the sea to Feralas. They believe he sought sanctuary in Eldre''Thalas, alive or dead.', 'quests 7494, 7492, 7488, 7489 descriptions and reward texts; quests 7481, 7482 descriptions and request text (my associate, the night elf scholar Runethorn); npc_text 6917 (Runethorn: on the verge of a breakthrough)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(35703, 1, 15, 255, 'Of late the pavilion has a second tenant, an unlikely neighbor for a Highborne: the orc Xerash Fireblade, who has set up among the old elven stones just north of Camp Mojache.', 'creature 36208 Xerash Fireblade in area 2518 (zone_areas); creature_template VerifiedBuild 10314 (patch 3.2.0); quest 3121 description (Xerash at the Lariss Pavilion, north of Camp Mojache); warcraft.wiki.gg/wiki/Xerash_Fireblade (added in patch 3.2.0); mod-individual-progression ipp_aware_npcs.sql (36208 ScriptName npc_ipp_wotlk_totc: CanBeSeen only from state 15, PROGRESSION_WOTLK_TIER_2)'),
(35705, 1, 0, 255, 'The answer lies on their own southern border. A battle map taken from their camps shows most of their forces turned south, away from Camp Mojache, beside a drawing of a great insect with tally marks beneath it. The gnolls are fighting a war on two fronts, and they spend their main strength against a foe to their south.', 'quest 2902 reward text (map, arrows to the south, insect with tick marks); quest 2903 reward text (two front war, main energy against a foe to their south)'),
(35705, 2, 0, 255, 'The hoarding of the gnolls once held a clue for Feathermoon Stronghold. Two large leather backpacks bearing the stronghold''s insignia, the packs of a missing courier, were found tacked to a tree in one of their camps.', 'quest 4131 description and reward text (gnolls keep items they scavenge; backpacks tacked to a tree, Feathermoon insignia); quest 4135 description'),
(35706, 1, 0, 255, 'Not every victim of the hive dies at once. The Zukk''ash seal some of those they overwhelm in hard, mucous pods large enough to hold a grown elf whole, and at least one prisoner has been found alive inside such a pod, paralyzed but breathing.', 'quest 4135 reward text (pod of an alien nature, mucous, large enough to encompass a humanoid); quest 4265 description (awoke paralyzed inside this pod, surprisingly still alive)'),
(35706, 2, 0, 255, 'In Orgrimmar, the scholar Zilzibin Drumlore knows the Zukk''ash by an older and more frightening name. They are the silithid, he warns, an ancient threat that the Horde keeps choosing to ignore, and far worse than anything the Alliance could muster.', 'quest 7732 reward text'),
(35715, 1, 2, 255, 'Of late a far greater shadow comes out of the Dream here. At times Emeriss, one of the great green dragons of Ysera''s flight, emerges beneath the Dream Bough, sick with corruption, and turns on any who come near.', 'warcraft.wiki.gg/wiki/Emeriss; DB: Emeriss 14889 spawn at -2872.7,1884.3 (area 1111); mod-individual-progression ipp_aware_npcs.sql (Dragons of Nightmare 14887-14890 phaseMask IPPPHASE) and IndividualProgression.cpp checkIPPhasing (AREA_DREAM_BOUGH 1111, AREA_JADEMIR_LAKE 1112: IPP_PHASE cast once PROGRESSION_ONYXIA, state 2, is passed); creature_template 14889 faction 50 (hostile)'),
(35716, 1, 0, 255, 'Up close the wreck tells more. A small crest of Feathermoon Stronghold is painted on its starboard side: it is almost surely the boat of the stronghold''s missing courier. In the mud beneath it lay a well kept knife, perhaps lost by whoever was aboard.', 'quest 4125 description and reward text (Raschal took a row boat; Feathermoon crest on the starboard side); quest 4127 description (knife in the mud, well cared for, lost by whoever was on the boat)'),
(35720, 1, 0, 255, 'Feathermoon''s scouts have news of the cave. In a recent naga excavation there, Lord Shalzaru himself uncovered an odd relic, and Latronicus Moonspear wants Shalzaru stopped and the relic brought back to the stronghold to be studied.', 'quest 2870 description (scouting reports, royals, Lord Shalzaru, odd relic from a recent excavation in a cave on the Isle of Dread); quest 2869 reward text (2870 offered as its next quest)'),
(35721, 1, 0, 255, 'Shandris keeps a quieter circle as well. She and the druid Quintis Jonespyre belong to the Protectorate, colleagues who take a close and private interest in the work being done for Arch Druid Fandral Staghelm in Darnassus, and who would much rather the Arch Druid did not hear of it.', 'quests 3788 and 3787 descriptions and reward texts (General Shandris Feathermoon and the Protectorate; keep our discussion from the ears of the Arch Druid)'),
(35723, 1, 0, 255, 'Lately Quintis has been asking quiet questions. He is concerned to know why Arch Druid Fandral Staghelm is using the name and the resources of the Cenarion Circle to gather vast amounts of morrowgrain, a grain that under the right conditions shows qualities like the herbs used in primitive curses.', 'quest 3791 description'),
(35723, 2, 0, 255, 'Handling the grain leaves him feeling strange, and he is uncomfortable even being near it. What Staghelm wants with so much of it Quintis cannot yet say, but he means to keep studying it, its alchemical uses among the rest, and he suspects that something is badly amiss.', 'quest 3791 reward text (these morrowgrain make me feel weird; what is Staghelm up to; alchemical uses; uncomfortable); quest 3792 reward text (something fishy going on)'),
(35725, 1, 0, 255, 'A weathered journal, found on the body of the dwarf Henrig Lonebrow, brought Falfindel grievous news. The druid Heralath, dying in Razorfen Kraul, had named him as the one who must be warned that the crone Charlga Razorflank was rousing her minions. With no time to send word to Darnassus, Falfindel called for a party to slay her and bring back her medallion.', 'item 5790 page_text 424-435; quest 1100 reward text; quest 1101 description'),
(35725, 2, 0, 255, 'With the crone laid to rest, the druids'' studies near the Kraul can go on, and Falfindel hopes at last to learn exactly what corrupted the resting place of the boar god Agamaggan, long held to be pure. Yet he fears that the answer lies in treachery.', 'quest 1101 reward text; item 5790 page_text (resting place of Agamaggan held to be pure)'),
(35725, 3, 0, 255, 'When a Feathermoon parcel at last reached him by other hands than its courier''s, Falfindel feared that some ill fate had befallen Raschal. He has noticed that the Woodpaw gnolls to the south have become highly agitated by some source beyond them, and he warns that the wilds there may have claimed the courier.', 'quest 4281 reward text'),
(35726, 1, 0, 255, 'Shay was found at last, wandering happily among the ruins, and brought home to his camp. On the way she shared her secret: a precious bell whose sound she loves so much that she always comes running back when it rings. Rockbiter was overjoyed to have her back, and delighted to learn that the bell would work whenever she wandered off again.', 'quest 2844 reward text (Shay: I am so glad you found me, isn''t this a beautiful place); quest 2845 description, request and reward text'),
(35728, 1, 0, 255, 'Once the horns were piled before him, Krueg meant to carry them back to Belgrom himself. Reminded that he had let the bounty slip, he grumbled that it would teach him to keep his mouth shut, and owning that the work was not his, he had the horns crated for the one who had earned them to carry to Belgrom in the Valley of Honor and claim the reward.', 'quest 2974 reward text (I''ll take these and be sure to tell Belgrom); quest 2976 description and reward text'),
(35731, 1, 0, 255, 'Falfindel grieved for both brave souls and would not let their valor go for nothing. There was no time to send word to Darnassus, so he called for a party to enter the Kraul, slay the crone and bring back Razorflank''s Medallion as proof that she was dead.', 'quest 1100 reward text; quest 1101 description'),
(35731, 2, 0, 255, 'The crone was laid to rest, and with her minions dealt with, the druids'' studies in the area could go on. Falfindel hoped to learn at last exactly what had corrupted the resting place of Agamaggan, but he feared that the answer lay in treachery as well.', 'quest 1101 reward text'),
(35732, 1, 0, 255, 'At the heart of the ruins stood a gazebo that did not belong. It was clearly newer than the stones around it, its sides bore a repeating band of glyphs of unknown origin and meaning, and its stone was warm to the touch.', 'quest 2866 reward text; quest 2867 description'),
(35732, 2, 0, 255, 'Shandris found the report disturbing: whatever the naga intended, their presence boded ill for the night elves'' push into Feralas. Unwilling to leave the stronghold open to the Horde by committing her full force, she gave the matter to her second, Latronicus Moonspear, whose plan was twofold: to weaken the naga in numbers and in command, and to learn what they were doing in the ruins.', 'quest 2867 reward text; quest 3130 description and reward text; quest 2869 description'),
(35732, 3, 0, 255, 'Hatecrest scales were gathered, and scouts named the royals who gave the naga their orders, among them the cruel Lord Shalzaru, who had dug up an odd relic in a cave on the Isle of Dread. Shalzaru was slain, throwing the naga into disarray, and Latronicus asked that his relic be taken to his wife Vestia to be studied.', 'quest 2869 reward text; quest 2870 description and reward text; quest 2871 description'),
(35732, 4, 0, 255, 'Vestia judged that the relic did not belong to the ruins, yet it was not of naga design either: it was something far more alien. Unraveling it will take time, and she has set herself to the research.', 'quest 2871 reward text'),
(35733, 1, 0, 255, 'Raschal''s row boat was found wrecked in the muddy water off the coast, its port side riddled with holes, as though something had tried to snap it in two. In the mud beneath it lay a well kept knife, and whoever found it had the uneasy feeling of not being alone in the water.', 'quest 4125 reward text; quest 4127 description'),
(35733, 2, 0, 255, 'Ginro had the knife taken to the stronghold''s druid, Quintis Jonespyre, who read its history by touch. In his vision Raschal carried two large backpacks inland, ran into Woodpaw gnolls and came back to his boat almost terrified, so distracted that he never noticed water elementals forming behind him. There the images stopped.', 'quest 4127 reward text; quest 4129 description; quest 4130 description'),
(35733, 3, 0, 255, 'Gnolls keep what they scavenge, and in one of the Woodpaw camps Raschal''s packs hung tacked to a tree. Inside were a parcel bound for Thalanaar and a hasty note signed by Raschal of Feathermoon: he had found insidious bug-like creatures south of the gnoll camps, in a place called the Writhing Deep, and gone to investigate them as a threat to all of Feralas.', 'quest 4131 description and reward text; quest 4135 description'),
(35733, 4, 0, 255, 'In the Writhing Deep he was found sealed in a hard, mucous pod of the Zukk''ash, paralyzed after the insects overwhelmed him, yet still alive. Freed from the hive, Raschal made his way home to Feathermoon, and Ginro swore that the one who saved him would always have a friend in him.', 'quest 4135 reward text; quest 4265 description and reward text'),
(35733, 5, 0, 255, 'Shandris Feathermoon gave her own thanks. The reports of the Zukk''ash had frightened the stronghold, and while Raschal''s report on the infestation of southeastern Feralas was filed in Darnassus, she sent a copy to Gracina Spiritmight, a priestess of the Temple of the Moon and an associate of the Protectorate with broad knowledge of such creatures.', 'quest 4266 description and reward text; quest 4267 description'),
(35734, 1, 0, 255, 'The pen was thrown open and the darters flew free, but Kindal knew they would not stay free for long. As she prepared their retribution, the two elves resolved to go on the offensive against the Grimtotem.', 'quest 2969 reward text; quest 2970 description'),
(35734, 2, 0, 255, 'Picking off naturalists, raiders and shamans in the camp below and in the camps to the east, the two elves soon counted their kills in the dozens, and the Grimtotem began hunting them like vipers in turn. Jer''kai wondered whether other tauren frowned on these, since many races have their less kindly cousins.', 'quest 2970 description, objectives, request and reward text'),
(35734, 3, 0, 255, 'With little to give out in the wilds, Jer''kai had sent her signet ring to High Priestess Tyrande Whisperwind in Darnassus as word that the two of them were well. In the meantime the Moonweavers saved a nest of sprite darter eggs whose mother had died before they reached her. The eggs were close to hatching, and they offered one to their helper as a pet, sending it first to the scholar Quentin at the race tracks of the Shimmering Flats.', 'quest 2972 description (signet ring to Tyrande); quest 3841 description (needs 2972 done)'),
(35734, 4, 0, 255, 'Quentin found the egg healthy and near maturation, a rare find now that poachers have hunted the darters of Feralas, and sent it on to Agnar Beastamer, the animal handler of Aerie Peak. Agnar had Silvermane stalker flanks gathered for its first meal, but the egg was readier than he thought, and the faerie dragon hatched to bond with the one who had carried it so far.', 'quest 3841 reward text; quests 3842, 3843, 4297 descriptions and reward texts; quest 4298 description and reward text'),
(35735, 1, 0, 255, 'Daryn was unimpressed. Troyas always thinks he has found something important, she grumbled, when anything of value in those ruins was hoarded long ago by the ogres or the harpies. Still, she owned a worn old history of Feralas, and she would lend it for a price: a picture of Gammerita, a giant snapjaw of the Hinterlands, taken with a device that the inventor Curgle Cranklehop built for her in Tanaris.', 'quest 2939 reward text; quest 2940 description and reward text; quest 2941 description'),
(35735, 2, 0, 255, 'With the book in hand, Troyas dared to hope that his find was the Stave of Equinex, the key to the Equinex Monolith in the Ruins of Ravenwind, west of the Dream Bough. Charged with the essence of the four flames that still burn there, Samha, Imbel, Byltan and Lahassa, it should unlock the monolith and the sacred artifact within.', 'quests 2943, 2944 reward texts; quest 2879 description'),
(35735, 3, 0, 255, 'Energized by the flames, the stave opened a small door in the monolith, and beams of light filled the ruins. The stone inside was brought back to Troyas, who, reading on, named it the Morrow Stone. He cannot yet say what it is for, but anything hidden away with such care must be of great significance.', 'quest 2879 reward text; quest 2942 description and reward text'),
(35736, 1, 0, 255, 'In times past the camp had always driven them back, but lately they pushed north far more often and more savagely, almost as if they were desperate. Hadoken''s answer was a stroke meant to throw them into chaos: five of their leaders, the Alphas, cut down in swift succession.', 'quest 2862 reward text; quest 2863 description'),
(35736, 2, 0, 255, 'The Alphas fell, but Hadoken still wanted to know what drove the gnolls, and a battle map taken from their camps told the tale. Most of its arrows pointed south, away from Camp Mojache, and beside them was drawn a great insect with tally marks beneath. The gnolls were fighting on two fronts, and their main strength was spent against a foe to their south.', 'quest 2863 reward text; quest 2902 description and reward text; quest 2903 reward text'),
(35736, 3, 0, 255, 'That foe was an insect race, the Zukk''ash of the Writhing Deep. Their swarms were thinned, and the giant Stinglasher, larger than its kin and wrapped in a strange aura, was cut open so that its glands could be studied. Yet nothing short of a full invasion would break the hive, and Hadoken sent all he had learned to Zilzibin Drumlore in the Drag of Orgrimmar, an expert on alien creatures.', 'quests 7730, 7731 descriptions and reward texts; quest 7732 description'),
(35736, 4, 0, 255, 'Zilzibin had been expecting the report. The Zukk''ash, he said, are nothing more than the silithid, an ancient threat that the Horde keeps choosing to ignore. Some think them a mindless nuisance, but they are a far, far worse threat than anything the Alliance could muster.', 'quest 7732 reward text'),
(35737, 1, 0, 255, 'The ogres, brutes and ogre magi of the outpost were cut down, and Rok Orhan believes that in time the land will heal. The fight then moved southwest to the High Wilderness, where stronger shamans, warlocks and maulers hold old night elf ruins amid withered trees and desecrated ground.', 'quest 2975 reward text; quest 2980 description'),
(35737, 2, 0, 255, 'Rok Orhan read the scroll as the plans for a dark ceremony, a ritual conducted by the Gordunni mage-lords. She sought one of their orbs, sure that the orb of a mage holds power enough to reveal more of the ceremony and of the magic the ogres wield.', 'quest 2979 description'),
(35737, 3, 0, 255, 'An orb was taken from a mage-lord, but Rok Orhan, a warrior who knows her enemy well, could not tell what it was capable of. She sent it to the mage Uthel''nay in the Darkbriar Lodge of Orgrimmar, who found it fascinating: very powerful, and very dangerous.', 'quest 2979 reward text; quest 3002 description and reward text'),
(35738, 1, 0, 255, 'The herbs prepared the vessel, and a first test proved both the ritual and the hunter: the fallen were shrunk and captured before their spirits could escape. Upon a violent death, Uzer''i explained, the muisek of a creature may flee to seek revenge, but once captured it can be used as he pleases. Then he turned the vessel on the allies of the night elves, beginning with the hippogryphs, whose spirits are loyal and steadfast.', 'quest 3122 reward text; quest 3123 description and reward text; quest 3124 description'),
(35738, 2, 0, 255, 'A muisek allowed to escape, Uzer''i warned, might take the form of an even greater creature, and no one would be safe from its vengeance, yet the work went on. Faerie dragons followed, fragile in body but strong in spirit; then the wandering treants the night elves have enlisted as protectors against the Horde; and last the mountain giants, who came down from their peaks to aid the night elves when the Burning Legion appeared in the world.', 'quest 3124 reward text; quests 3125, 3126, 3127 descriptions'),
(35738, 3, 0, 255, 'With the muisek of all these creatures and the materials gathered, Uzer''i set about the difficult work of imbuing the spirits into weapons. When he was done, the muisek had been sealed forever into the weapons of the Horde, their energy for the bearer to wield as his own.', 'quest 3127 reward text; quest 3129 description and reward text'),
(35739, 1, 0, 255, 'Lethtendris fell in the Warpwood Quarter, and her web was carried back to Latronicus. Elves of her ilk, he said, believe themselves masters of magic and do not see that they are slaves to their own addiction. Her death saddened him, but it was necessary. He will have the web''s energies released safely over a wide area and then destroy it, so that it can serve no one again.', 'quest 7488 description and reward text'),
(35739, 2, 0, 255, 'Lethtendris fell in the Warpwood Quarter, and her web was carried back to Talo. It holds vast stores of the magic of Dire Maul, and he feared what harm might come if one so irresponsible had harnessed them. He was saddened by her death, but knew she would never have parted with the web while she lived. He will send it to more responsible students of magic, to be the new wardens of its power.', 'quest 7489 description and reward text'),
(35739, 3, 0, 255, 'The search for Kariel Winthalus ended in disappointment. No trace of the elven master was found in the halls, and the artifacts he carried are lost. It is a shame and a tragedy, the scholars lament, for they had believed themselves on the verge of a breakthrough.', 'quests 7481, 7482 reward texts; npc_text 6917 (Runethorn: on the verge of a breakthrough)');
